package com.bank.integrity;

import java.util.Arrays;
import java.util.logging.*;

public class BankDemo {
    private static final Logger log = Logger.getLogger(BankDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Sealed permitted set: " +
            Arrays.toString(AccountProduct.class.getPermittedSubclasses()));

        SealBreakAttempt attempt = new SealBreakAttempt();
        attempt.tryReflectiveSubclass();

        // ── Why bytecode manipulation CAN forge the seal (documentation only) ──
        // The sealed guarantee lives in the PermittedSubclasses attribute of the
        // AccountProduct classfile. A tool like ASM could:
        //   1. read AccountProduct.class
        //   2. append "RogueProduct" to PermittedSubclasses (or delete the attribute)
        //   3. write a tampered AccountProduct.class
        // If the JVM then loads the TAMPERED classfile, the verifier only checks
        // consistency against that forged attribute, so RogueProduct would load.
        //
        // REAL defense is NOT sealing — it is:
        //   • signed jars (jarsigner) + signature verification at load
        //   • immutable, signed container images
        //   • JPMS strong encapsulation + not loading untrusted classes
        log.warning("Sealing is an INTEGRITY guarantee, not a security sandbox. "
            + "Tamper protection comes from signed artifacts, not from sealed.");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
