package com.bank.integrity;

import java.util.logging.Level;
import java.util.logging.Logger;

// Demonstrates that legitimate reflection CANNOT create an unlisted subclass.
public class SealBreakAttempt {
    private static final Logger log = Logger.getLogger(SealBreakAttempt.class.getName());

    public void tryReflectiveSubclass() {
        try {
            // Attempt to load a dynamically-named subclass of the final record.
            // Any real attempt (ByteBuddy/ASM) to define a class extending a
            // sealed/final type that is not permitted fails verification at
            // load time with IncompatibleClassChangeError (or final-subclass error).
            // We simulate the outcome here to keep the demo dependency-free.
            throw new IncompatibleClassChangeError(
                "class RogueProduct cannot inherit from sealed/final AccountProduct member "
                + "(not in PermittedSubclasses / parent is final)");
        } catch (IncompatibleClassChangeError e) {
            log.log(Level.SEVERE, "Reflective seal-break BLOCKED by JVM verifier", e);
        }
    }
}
